#include <stdio.h>

void twoSum(int nums[], int n, int target, int result[2]) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (nums[i] + nums[j] == target) {
                result[0] = i;
                result[1] = j;
                return;
            }
        }
    }
    result[0] = -1;
    result[1] = -1;
}

int main() {
    int nums[] = {2, 7, 11, 15};
    int result[2];
    twoSum(nums, 4, 9, result);
    printf("[%d, %d]\n", result[0], result[1]); // [0, 1]
    return 0;
}

